window.TIMING = {"open-wolves":{"dur":33.82,"beats":[{"start":2.2,"sents":[{"start":2.2,"end":13.24,"cap":"In 1995 and 1996, sixty-six gray wolves were released into central Idaho and Yellowstone National Park, about seventy years after the last of Yellowstone’s wolves were killed."},{"start":13.64,"end":17.99,"cap":"Their descendants now number at least twenty-eight hundred, across six states."}],"end":17.99},{"start":18.74,"sents":[{"start":18.74,"end":21.62,"cap":"Within twenty years a story had traveled around the world."},{"start":22.02,"end":28.32,"cap":"The wolves had frightened the elk, the willows and aspen had grown back, and even the rivers had changed their course."}],"end":28.32},{"start":29.07,"sents":[{"start":29.07,"end":30.44,"cap":"It is a beautiful story."},{"start":30.84,"end":31.52,"cap":"Is it true?"}],"end":31.52}],"sig":"469:0,0,1"},"open-bands":{"dur":63.73,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.21,"cap":"To answer, we have to pull apart three things that are easy to blur."},{"start":4.61,"end":6.22,"cap":"What did anyone actually observe?"},{"start":6.62,"end":9.99,"cap":"What was inferred from those observations, and under which assumptions?"},{"start":10.39,"end":12.32,"cap":"And what are we entitled to claim we know?"}],"end":12.32},{"start":13.07,"sents":[{"start":13.07,"end":20.44,"cap":"Ecologists have argued over those answers for a quarter of a century, counting elk, measuring aspen, and collaring predators."},{"start":20.84,"end":24.29,"cap":"The argument is one of the best lessons there is in how science works."}],"end":24.29},{"start":25.04,"sents":[{"start":25.04,"end":43.29,"cap":"So this film follows predators, and what they do and do not do to the world around them, through the philosophy of science: what science is trying to do, how we can know anything about nature, induction and falsification, paradigms and models, causes and confounders, Bayesian belief, and replication."}],"end":43.29},{"start":44.04,"sents":[{"start":44.04,"end":49.19,"cap":"And we will ask a harder question: what counts as science, and who gets to decide?"}],"end":49.19},{"start":50.74,"sents":[{"start":50.74,"end":51.79,"cap":"Two guides will help."},{"start":52.19,"end":56.99,"cap":"The badge in the corner shows whether an idea concerns observation, inference, or claim."},{"start":57.39,"end":61.23,"cap":"The lexicon on the right collects the terms an examiner may ask you to define."}],"end":61.23}],"sig":"989:0,0,0,0.8,1.2"},"aims-card":{"dur":7.12,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.68,"cap":"Chapter one."},{"start":2.08,"end":5.52,"cap":"The aims of science: what all this effort is for."}],"end":5.52}],"sig":"62:0"},"aims-elk":{"dur":59.43,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.28,"cap":"Begin with one herd."},{"start":2.68,"end":8.39,"cap":"Just before wolves returned, the elk wintering on Yellowstone’s Northern Range numbered more than nineteen thousand."},{"start":8.79,"end":13.13,"cap":"By 2013 the count had fallen to 3,915."},{"start":13.53,"end":16.15,"cap":"Today it is roughly seven to nine thousand."}],"end":16.15},{"start":16.9,"sents":[{"start":16.9,"end":19,"cap":"Numbers like these invite different aims."},{"start":19.4,"end":21.55,"cap":"Explain: why did the herd decline?"},{"start":21.95,"end":24.74,"cap":"Predict: will willows along the streams recover?"},{"start":25.14,"end":28.44,"cap":"Intervene: would killing predators bring the elk back?"}],"end":28.44},{"start":29.19,"sents":[{"start":29.19,"end":30.51,"cap":"The aims can come apart."},{"start":30.91,"end":41.7,"cap":"Predators kill many young ungulates, yet across fifty-two predator-removal experiments, removal often raised juvenile survival but rarely raised adult survival or abundance."},{"start":42.1,"end":45.74,"cap":"A true causal fact does not guarantee the outcome of an intervention."}],"end":45.74},{"start":46.49,"sents":[{"start":46.49,"end":51.75,"cap":"Description, explanation, prediction, understanding, and control are all aims of science."},{"start":52.15,"end":58.13,"cap":"Traditions rank them differently, and much confusion about what science is begins with confusion about what it is for."}],"end":58.13}],"sig":"914:0,0,0,0"},"aims-explain":{"dur":52.24,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":9.22,"cap":"In 1948, Carl Hempel and Paul Oppenheim proposed that to explain an event is to deduce it from general laws and initial conditions."},{"start":9.62,"end":15.74,"cap":"On their deductive-nomological model, explanation and prediction are the same argument, made at different times."}],"end":15.74},{"start":16.49,"sents":[{"start":16.49,"end":17.51,"cap":"The symmetry breaks."},{"start":17.91,"end":23.5,"cap":"A flagpole’s shadow and the sun’s angle let you deduce the pole’s height, but the shadow does not explain it."},{"start":23.9,"end":32.47,"cap":"A correlative distribution model can predict where a species lives without saying why, and a mechanistic model can explain a process yet predict it poorly."}],"end":32.47},{"start":33.22,"sents":[{"start":33.22,"end":38.05,"cap":"Wesley Salmon answered that explanation shows the causes and mechanisms that produced an event."},{"start":38.45,"end":42.77,"cap":"Philip Kitcher answered that it unifies many phenomena under a few patterns of argument."},{"start":43.17,"end":50.94,"cap":"Trophic cascade theory aspires to both: one mechanism linking otters and kelp, wolves and aspen, spiders and grass."}],"end":50.94}],"sig":"832:0,0,0"},"aims-real":{"dur":55.47,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.97,"cap":"When a theory works, is it true?"},{"start":3.37,"end":6.03,"cap":"Scientific realists say yes, approximately."},{"start":6.43,"end":11.59,"cap":"Hilary Putnam argued that realism is the only view that does not make the success of science a miracle."}],"end":11.59},{"start":12.34,"sents":[{"start":12.34,"end":19.03,"cap":"Larry Laudan replied with history: the ether, caloric, and phlogiston all succeeded, and all were false."},{"start":19.43,"end":22.38,"cap":"If success did not guarantee truth then, why now?"},{"start":22.78,"end":24.85,"cap":"This is the pessimistic meta-induction."}],"end":24.85},{"start":25.6,"sents":[{"start":25.6,"end":27.62,"cap":"Antirealists offer humbler aims."},{"start":28.02,"end":30.39,"cap":"Instrumentalists treat theories as tools."},{"start":30.79,"end":36.13,"cap":"Bas van Fraassen asks only that a theory be empirically adequate, true about what is observable."},{"start":36.53,"end":40.54,"cap":"Structural realists keep the mathematical structure that survives theory change."}],"end":40.54},{"start":41.29,"sents":[{"start":41.29,"end":48.67,"cap":"Ecology is full of things no one observes directly: niches, carrying capacity, predation risk, a landscape of fear."},{"start":49.07,"end":51.51,"cap":"Real features of the world, or useful summaries?"},{"start":51.91,"end":54.17,"cap":"Your answer shapes what you think a study has shown."}],"end":54.17}],"sig":"846:0,0,0,0"},"aims-bands":{"dur":65.71,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.67,"cap":"This film sorts every idea into three bands."},{"start":4.07,"end":7.9,"cap":"Observation: records made by senses and instruments."},{"start":8.3,"end":12.32,"cap":"Inference: reasoning from records through models and assumptions."},{"start":12.72,"end":17.94,"cap":"Claim: a statement of knowledge, with its scope and confidence, offered for scrutiny."}],"end":17.94},{"start":18.69,"sents":[{"start":18.69,"end":21.74,"cap":"The bands follow Stephen Toulmin’s model of an argument."},{"start":22.14,"end":28.06,"cap":"Data support a claim through a warrant, a general rule that licenses the step, which rests on backing."},{"start":28.46,"end":33.59,"cap":"A qualifier says how strongly the claim holds; a rebuttal says when it would not."}],"end":33.59},{"start":34.34,"sents":[{"start":34.34,"end":35.36,"cap":"Try it on the herd."},{"start":35.76,"end":39.21,"cap":"Data: elk counts fell after 1995."},{"start":39.61,"end":41.82,"cap":"Warrant: predators can reduce prey."},{"start":42.22,"end":44.59,"cap":"Claim: wolves caused the decline."},{"start":44.99,"end":46.58,"cap":"Qualifier: in part."},{"start":46.98,"end":54.22,"cap":"Rebuttal: unless hunting and drought did most of the work, which, for the first decade, a demographic analysis found they did."}],"end":54.22},{"start":54.97,"sents":[{"start":54.97,"end":64.41,"cap":"Each band adds assumptions, and each fails in its own way: observations can be biased, inferences confounded, and claims can outrun their warrant."}],"end":64.41}],"sig":"909:0,0,0,0"},"know-card":{"dur":7.51,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.66,"cap":"Chapter two."},{"start":2.06,"end":5.91,"cap":"Knowing nature: what knowledge is, and the traditions that seek it."}],"end":5.91}],"sig":"80:0"},"know-jtb":{"dur":65.04,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":5.25,"cap":"Epistemology is the study of knowledge: what it is, and how we get it."},{"start":5.65,"end":8.73,"cap":"A classic answer says knowledge is justified true belief."},{"start":9.13,"end":12.49,"cap":"You believe it, it is true, and you have good reason to believe it."}],"end":12.49},{"start":13.24,"sents":[{"start":13.24,"end":16.87,"cap":"In 1963, Edmund Gettier showed that is not enough."},{"start":17.27,"end":22.5,"cap":"A biologist glimpses a coyote, takes it for a wolf, and concludes a wolf is in the valley."},{"start":22.9,"end":24.96,"cap":"One is, out of sight behind a ridge."},{"start":25.36,"end":29.36,"cap":"The belief is justified and true, but it is luck, not knowledge."}],"end":29.36},{"start":30.11,"sents":[{"start":30.11,"end":31.8,"cap":"Where does justification come from?"},{"start":32.2,"end":36.24,"cap":"Empiricists answer experience; rationalists, reason."},{"start":36.64,"end":42.89,"cap":"Foundationalists rest knowledge on basic beliefs; coherentists, on how beliefs support one another."},{"start":43.29,"end":47.76,"cap":"And David Hume warned that no amount of past experience logically guarantees the future."}],"end":47.76},{"start":48.51,"sents":[{"start":48.51,"end":56.88,"cap":"Most scientists today are fallibilists, after Charles Sanders Peirce: any belief might be wrong, so inquiry must stay open to correction."},{"start":57.28,"end":63.74,"cap":"Willard Quine went further and treated epistemology itself as part of science, the study of how real knowers learn."}],"end":63.74}],"sig":"971:0,0,0,0"},"know-four":{"dur":47.76,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.09,"cap":"Research traditions differ in how they answer four questions."},{"start":4.49,"end":6.73,"cap":"Ontology: what exists to be known?"},{"start":7.13,"end":9.35,"cap":"Epistemology: how can we know it?"},{"start":9.75,"end":12.62,"cap":"Methodology: how do we go about finding out?"},{"start":13.02,"end":16.76,"cap":"Axiology: what do we value in research, and what do we owe?"}],"end":16.76},{"start":17.51,"sents":[{"start":17.51,"end":23.16,"cap":"Egon Guba and Yvonna Lincoln compared research paradigms by the first three, and later added the fourth."},{"start":23.56,"end":32.04,"cap":"A warning about the word: paradigm here means a broad research tradition, not quite Thomas Kuhn’s sense, which we meet in chapter five."}],"end":32.04},{"start":32.79,"sents":[{"start":32.79,"end":40.53,"cap":"We will follow two broad traditions: positivism and its successor, postpositivism; and interpretivism."},{"start":40.93,"end":46.46,"cap":"Each is internally diverse, none is a single view, and neither belongs to a single discipline."}],"end":46.46}],"sig":"674:0,0,0"},"know-pos":{"dur":54.43,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":9.32,"cap":"Auguste Comte coined positivism in the 1830s: knowledge comes from observation and the laws that summarize it, not from metaphysics."},{"start":9.72,"end":17.86,"cap":"In the 1920s the Vienna Circle sharpened it into logical positivism, and A. J. Ayer carried its verification principle into English philosophy."}],"end":17.86},{"start":18.61,"sents":[{"start":18.61,"end":25.14,"cap":"A statement is meaningful, the principle said, only if observation could verify it or it is true by definition."},{"start":25.54,"end":28.74,"cap":"The principle failed by its own test: it is neither."},{"start":29.14,"end":34,"cap":"And it would have ruled out much of physics, whose theoretical terms are never observed directly."}],"end":34},{"start":34.75,"sents":[{"start":34.75,"end":38.04,"cap":"What most ecologists practice today is postpositivism."},{"start":38.44,"end":50.11,"cap":"A real world exists but is imperfectly known; every observation is fallible; so we use design, statistics, and replication to approach the truth, and hold conclusions provisionally."},{"start":50.51,"end":53.13,"cap":"Critical realism gives this stance its philosophy."}],"end":53.13}],"sig":"825:0,0,0"},"know-interp":{"dur":51.66,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":6.41,"cap":"In the late nineteenth century, Wilhelm Dilthey argued that the human sciences need their own method."},{"start":6.81,"end":10.83,"cap":"Nature we explain, from outside, by causes: Erklären."},{"start":11.23,"end":16.24,"cap":"Human life we understand, from inside, through meanings: Verstehen."}],"end":16.24},{"start":16.99,"sents":[{"start":16.99,"end":24.36,"cap":"Max Weber built Verstehen into sociology, and Charles Taylor argued that the social sciences are irreducibly interpretive."},{"start":24.76,"end":33.63,"cap":"Peter Berger and Thomas Luckmann showed how much of social reality, from property lines to protected-area boundaries, is constructed and sustained by people."}],"end":33.63},{"start":34.38,"sents":[{"start":34.38,"end":38.19,"cap":"Wildlife science meets interpretivism wherever people are part of the system."},{"start":38.59,"end":45.39,"cap":"Whether a wolf is a symbol of wilderness, a threat to a ranch, or a rival for the hunter’s elk depends on who is asked."},{"start":45.79,"end":50.36,"cap":"Ecologists call the number of carnivores people will tolerate the social carrying capacity."}],"end":50.36}],"sig":"808:0,0,0"},"know-lenses":{"dur":31.64,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.47,"cap":"Look at the Northern Range elk through each lens."},{"start":3.87,"end":9.43,"cap":"A postpositivist counts animals, estimates survival, and models the causes of decline."},{"start":9.83,"end":13.25,"cap":"The question is what happened, and how much each factor contributed."}],"end":13.25},{"start":14,"sents":[{"start":14,"end":25.36,"cap":"An interpretivist asks what the herd means to ranchers, hunters, outfitters, and visitors, and how those meanings shape management, from hunting quotas to tolerance of elk on irrigated fields outside the park."},{"start":25.76,"end":30.34,"cap":"One herd, two kinds of question; each lens shows something the other misses."}],"end":30.34}],"sig":"492:0,0"},"infer-card":{"dur":7.37,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.66,"cap":"Chapter three."},{"start":2.06,"end":5.77,"cap":"Inference: deduction, induction, and abduction."}],"end":5.77}],"sig":"62:0"},"infer-kaibab":{"dur":44.32,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":6.87,"cap":"Aldo Leopold supported killing predators in the 1910s and 1920s, then changed his mind."},{"start":7.27,"end":15.07,"cap":"On Arizona’s Kaibab Plateau, he wrote, deer had irrupted after wolves and pumas were removed, then stripped the range of browse and starved."}],"end":15.07},{"start":15.82,"sents":[{"start":15.82,"end":18.5,"cap":"Rachel Carson retold the story in Silent Spring."},{"start":18.9,"end":26.37,"cap":"It became a founding example for the green world hypothesis: the world is green because predators keep herbivores in check."}],"end":26.37},{"start":27.12,"sents":[{"start":27.12,"end":33.18,"cap":"In 1970, Graeme Caughley examined the Kaibab records and called them unreliable and inconsistent."},{"start":33.58,"end":39.5,"cap":"He suggested the deer increase may have followed the removal of cattle, a rival explanation no one had ruled out."},{"start":39.9,"end":43.02,"cap":"A general rule had been built on one poorly measured case."}],"end":43.02}],"sig":"670:0,0,0"},"infer-three":{"dur":61.98,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.77,"cap":"Deduction moves from premises to what must follow."},{"start":4.17,"end":7.62,"cap":"If all elk are ungulates, and this is an elk, it is an ungulate."},{"start":8.02,"end":14.36,"cap":"A valid deduction cannot have true premises and a false conclusion; a sound one is valid with true premises."},{"start":14.76,"end":17.67,"cap":"But deduction never says more than its premises contain."}],"end":17.67},{"start":18.42,"sents":[{"start":18.42,"end":24.87,"cap":"Induction generalizes from cases: every swan seen so far is white, so all swans are white."},{"start":25.27,"end":28.34,"cap":"It is ampliative, adding content, and fallible."},{"start":28.74,"end":33.4,"cap":"David Hume showed it cannot be justified without assuming the future will resemble the past."},{"start":33.8,"end":37.01,"cap":"Europeans learned this in Australia, from black swans."}],"end":37.01},{"start":37.76,"sents":[{"start":37.76,"end":44.29,"cap":"Abduction, Charles Sanders Peirce’s term, reasons from a surprising fact to the hypothesis that would explain it."},{"start":44.69,"end":53.48,"cap":"Peter Lipton calls this inference to the best explanation, and warns that the loveliest explanation, the one that would explain the most, is not always the likeliest."}],"end":53.48},{"start":54.23,"sents":[{"start":54.23,"end":60.68,"cap":"The Kaibab story was an induction from one case, joined to an abduction whose loveliness hid an untested rival."}],"end":60.68}],"sig":"960:0,0,0,0"},"infer-strong":{"dur":55.13,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.61,"cap":"Science runs the three together."},{"start":3.01,"end":9.42,"cap":"The hypothetico-deductive method takes a hypothesis, deduces what should be observed if it is true, and checks."},{"start":9.82,"end":12.79,"cap":"In Yellowstone, aspen grew taller after wolves returned."},{"start":13.19,"end":15.35,"cap":"The abduction: wolves did it."}],"end":15.35},{"start":16.1,"sents":[{"start":16.1,"end":16.63,"cap":"But how?"},{"start":17.03,"end":21.86,"cap":"If fear kept elk away from risky places, browsing should drop most where wolves hunt."},{"start":22.26,"end":26.85,"cap":"If wolves simply reduced elk numbers, recovery should track elk density everywhere."},{"start":27.25,"end":31.14,"cap":"Two mechanisms, two different predictions, testable in the field."}],"end":31.14},{"start":31.89,"sents":[{"start":31.89,"end":38.48,"cap":"In 1890, Thomas Chamberlin urged scientists to hold multiple working hypotheses, so they would not fall in love with one."},{"start":38.88,"end":48.12,"cap":"In 1964, John Platt called the method strong inference: devise rival hypotheses, design experiments that exclude some, and repeat."},{"start":48.52,"end":53.83,"cap":"In 2015, Adam Ford and Jacob Goheen asked trophic-cascade research to do exactly that."}],"end":53.83}],"sig":"816:0,0,0"},"fals-card":{"dur":6,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.68,"cap":"Chapter four."},{"start":2.08,"end":4.09,"cap":"Falsification, and why it is not enough."}],"end":4.09}],"sig":"54:0"},"fals-asym":{"dur":41.42,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.31,"cap":"Karl Popper turned Hume’s problem around."},{"start":3.71,"end":8.76,"cap":"No number of white swans proves that all swans are white, but one black swan proves they are not."},{"start":9.16,"end":12.53,"cap":"Verification and falsification are logically asymmetric."}],"end":12.53},{"start":13.28,"sents":[{"start":13.28,"end":18.37,"cap":"So science, Popper argued, advances by bold conjectures that risk refutation."},{"start":18.77,"end":22.86,"cap":"A theory that survives a severe test is corroborated, never proven."},{"start":23.26,"end":27.86,"cap":"In 1919, Einstein’s theory predicted how far starlight would bend around the sun."},{"start":28.26,"end":29.14,"cap":"It could have failed."},{"start":29.54,"end":30.23,"cap":"It did not."}],"end":30.23},{"start":30.98,"sents":[{"start":30.98,"end":35.72,"cap":"Falsifiability became Popper’s criterion for separating science from pseudoscience."},{"start":36.12,"end":40.12,"cap":"A theory that could explain any outcome, whatever happened, explained nothing."}],"end":40.12}],"sig":"621:0,0,0"},"fals-fear":{"dur":51.71,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.4,"cap":"Here is a bold conjecture."},{"start":2.8,"end":10.16,"cap":"Wolves reduce elk numbers not only by killing them but by frightening them: vigilant, stressed elk eat less and conceive less."},{"start":10.56,"end":17.61,"cap":"In 2007, Scott Creel and colleagues reported that elk progesterone fell as wolves became more numerous relative to elk."}],"end":17.61},{"start":18.36,"sents":[{"start":18.36,"end":23.83,"cap":"Later studies measured pregnancy directly, from hunter-killed cows and from blood samples of live elk."},{"start":24.23,"end":27.66,"cap":"Pregnancy rates were uniformly high, whatever the wolf risk."},{"start":28.06,"end":31.81,"cap":"And collared elk met wolves too rarely for fear to disrupt their foraging."}],"end":31.81},{"start":32.56,"sents":[{"start":32.56,"end":34.39,"cap":"Is the fear hypothesis falsified?"},{"start":34.79,"end":35.33,"cap":"Not quite."},{"start":35.73,"end":41.73,"cap":"The first test assumed that progesterone indexes pregnancy, and that the elk-to-wolf ratio measures risk."},{"start":42.13,"end":45.17,"cap":"If either auxiliary was wrong, the hypothesis survives."},{"start":45.57,"end":50.41,"cap":"Fear effects are well documented in behavior, but not yet shown to change elk demography."}],"end":50.41}],"sig":"809:0,0,0"},"fals-dq":{"dur":82.12,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.69,"cap":"Pierre Duhem saw the problem in 1906."},{"start":4.09,"end":10.34,"cap":"A prediction follows from a hypothesis plus auxiliary assumptions, so a failed prediction refutes only the bundle."},{"start":10.74,"end":12.72,"cap":"Willard Quine generalized the point."},{"start":13.12,"end":15.4,"cap":"Logic alone never says which part to blame."}],"end":15.4},{"start":16.15,"sents":[{"start":16.15,"end":18.53,"cap":"Sometimes blaming an auxiliary is brilliant."},{"start":18.93,"end":24.58,"cap":"When Uranus strayed from its predicted orbit, astronomers proposed an unseen planet and found Neptune."},{"start":24.98,"end":30.08,"cap":"When Mercury strayed, the same move predicted a planet, Vulcan, that does not exist."},{"start":30.48,"end":32.11,"cap":"The fault lay in Newton’s theory."}],"end":32.11},{"start":32.86,"sents":[{"start":32.86,"end":35.06,"cap":"Imre Lakatos made the choice principled."},{"start":35.46,"end":40.15,"cap":"A research program has a hard core, protected by a belt of auxiliary hypotheses."},{"start":40.55,"end":45.98,"cap":"Adjusting the belt is progressive if it predicts new facts, and degenerating if it only patches failures."},{"start":46.38,"end":48.76,"cap":"All theories, he noted, are born refuted."}],"end":48.76},{"start":49.51,"sents":[{"start":49.51,"end":61.54,"cap":"In Yellowstone, after a landscape test found no effect of predation risk on aspen browsing, proponents argued that elk sense risk where they first meet wolves, not where wolves kill them, nearly a kilometer away on average."},{"start":61.94,"end":65.35,"cap":"Lakatos asks: did the adjustment predict anything new?"}],"end":65.35},{"start":66.1,"sents":[{"start":66.1,"end":66.91,"cap":"Two cautions."},{"start":67.31,"end":71.61,"cap":"Probabilistic hypotheses cannot be strictly falsified by any single result."},{"start":72.01,"end":80.82,"cap":"And a null hypothesis significance test is not Popperian falsification: rejecting a null of no effect at all is not a risky test of a research hypothesis."}],"end":80.82}],"sig":"1298:0,0,0,0,0"},"kuhn-card":{"dur":6.13,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.69,"cap":"Chapter five."},{"start":2.09,"end":4.53,"cap":"Paradigms, and how science changes its mind."}],"end":4.53}],"sig":"58:0"},"kuhn-cycle":{"dur":47.82,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":10.77,"cap":"In 1962, Thomas Kuhn described science not as a steady march of conjectures and refutations, but as long periods of normal science punctuated by revolutions."}],"end":10.77},{"start":11.52,"sents":[{"start":11.52,"end":22.23,"cap":"In normal science a community shares a paradigm: a disciplinary matrix of theories, methods, and values, anchored by exemplars, model solutions that students learn to imitate."},{"start":22.63,"end":24.54,"cap":"Research is puzzle-solving within it."},{"start":24.94,"end":28.64,"cap":"Anomalies are set aside, until they accumulate into a crisis."}],"end":28.64},{"start":29.39,"sents":[{"start":29.39,"end":31.46,"cap":"A revolution replaces the paradigm."},{"start":31.86,"end":37.37,"cap":"Kuhn compared it to a gestalt switch: the same figure seen first as a duck, then as a rabbit."},{"start":37.77,"end":46.52,"cap":"Rival paradigms can be incommensurable, disagreeing about which problems matter and what would count as a solution, so no neutral test decides between them."}],"end":46.52}],"sig":"720:0,0,0"},"kuhn-vermin":{"dur":64.87,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":8.37,"cap":"For the first half of the twentieth century, killing predators was normal practice, carried out by government hunters across the American West."},{"start":8.77,"end":15.97,"cap":"By 1994, wolves in the lower forty-eight states survived only around the northern Great Lakes and near Glacier National Park."}],"end":15.97},{"start":16.72,"sents":[{"start":16.72,"end":19.45,"cap":"Leopold’s own reversal reads like a gestalt switch."},{"start":19.85,"end":28.71,"cap":"In “Thinking Like a Mountain,” he describes watching a fierce green fire die in the eyes of a wolf he had shot, and realizing that the mountain saw the wolf differently than he did."}],"end":28.71},{"start":29.46,"sents":[{"start":29.46,"end":45.58,"cap":"A new program grew around top-down control, with its own exemplars: killer whales, sea otters, urchins, and kelp; ecological meltdown on predator-free islands in a Venezuelan reservoir; songbirds lost to mesopredators once coyotes disappeared."},{"start":45.98,"end":47.89,"cap":"Yellowstone became the textbook case."}],"end":47.89},{"start":48.64,"sents":[{"start":48.64,"end":53.24,"cap":"Normal science followed, extending the pattern to willow, cottonwood, and other parks."},{"start":53.64,"end":56.33,"cap":"So did anomalies, which we meet in the chapters ahead."},{"start":56.73,"end":61.39,"cap":"Did ecology then undergo a revolution, or absorb its anomalies as context?"},{"start":61.79,"end":63.57,"cap":"Kuhn gives you the tools to decide."}],"end":63.57}],"sig":"1038:0,0,0,0"},"kuhn-choice":{"dur":43.08,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.32,"cap":"If there is no neutral test, is theory choice irrational?"},{"start":4.72,"end":12.63,"cap":"Kuhn said no. Scientists share values: accuracy, consistency, scope, simplicity, and fruitfulness."},{"start":13.03,"end":17.07,"cap":"But they weigh them differently, so the values guide judgment without dictating it."}],"end":17.07},{"start":17.82,"sents":[{"start":17.82,"end":19.27,"cap":"Critics pushed both ways."},{"start":19.67,"end":23.16,"cap":"Lakatos thought programs could be ranked objectively by their progress."},{"start":23.56,"end":30.98,"cap":"Paul Feyerabend argued that every rule of method has been broken by some great scientist, so the only universal rule is “anything goes.”"},{"start":31.38,"end":34.75,"cap":"Larry Laudan judged traditions by their success at solving problems."}],"end":34.75},{"start":35.5,"sents":[{"start":35.5,"end":41.78,"cap":"Ecology has its own candidate revolution, from the balance of nature to non-equilibrium and patch dynamics."}],"end":41.78}],"sig":"657:0,0,0"},"obs-card":{"dur":6,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.75,"cap":"Chapter six."},{"start":2.15,"end":4.19,"cap":"Observation, and the theory it carries."}],"end":4.19}],"sig":"52:0"},"obs-seeing":{"dur":38.36,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.27,"cap":"Is there such a thing as a pure observation?"},{"start":3.67,"end":8.87,"cap":"Norwood Russell Hanson asked us to imagine Tycho Brahe and Johannes Kepler on a hill at dawn."},{"start":9.27,"end":12.83,"cap":"Tycho, who believed the earth stood still, sees the sun rise."},{"start":13.23,"end":15.17,"cap":"Kepler sees the horizon turn away."},{"start":15.57,"end":17.43,"cap":"The same light, seen differently."}],"end":17.43},{"start":18.18,"sents":[{"start":18.18,"end":25.48,"cap":"Observation is theory-laden: what we notice, how we describe it, and what we record depend on the concepts we bring."},{"start":25.88,"end":28.6,"cap":"James Bogen and James Woodward add a distinction."},{"start":29,"end":30.58,"cap":"Data are the records we collect."},{"start":30.98,"end":37.06,"cap":"Phenomena are the stable features of the world we infer from them, and theories explain phenomena, not data."}],"end":37.06}],"sig":"580:0,0"},"obs-stems":{"dur":64.55,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.22,"cap":"How do you see whether aspen are recovering?"},{"start":3.62,"end":11.39,"cap":"William Ripple and Robert Beschta measured the five tallest young aspen in each stand, reasoning that recovery would show first among the leaders."},{"start":11.79,"end":17.79,"cap":"Matthew Kauffman and colleagues measured every young aspen in random plots, and found no difference with predation risk."}],"end":17.79},{"start":18.54,"sents":[{"start":18.54,"end":29.2,"cap":"Revisiting the stands in 2012, Luke Painter and colleagues used both designs, random plots and the tallest stems, and drew their main range-wide conclusion largely from the random samples."},{"start":29.6,"end":36.7,"cap":"Up to sixty-five percent of stands had at least one sapling taller than two hundred centimeters, the height at which aspen escape browsing elk."}],"end":36.7},{"start":37.45,"sents":[{"start":37.45,"end":40.44,"cap":"Then Elaine Brice and colleagues compared the two designs."},{"start":40.84,"end":44.97,"cap":"Both detected a cascade, but random sampling showed a much weaker signal."},{"start":45.37,"end":50.93,"cap":"The tallest stems can show whether a cascade is happening; only a random sample can show how strong it is."}],"end":50.93},{"start":51.68,"sents":[{"start":51.68,"end":57.44,"cap":"Willow told a similar story: studies concentrated at well-watered sites overstated its recovery."},{"start":57.84,"end":59.31,"cap":"Neither design was dishonest."},{"start":59.71,"end":63.25,"cap":"Each embodied a different question, and the question shaped what was seen."}],"end":63.25}],"sig":"1087:0,0,0,0"},"obs-instr":{"dur":66.01,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.93,"cap":"Instruments are theory made physical."},{"start":3.33,"end":11.06,"cap":"Early studies tracked elk with VHF radio collars, located a few times a month, and could only map predation risk as fixed in space."},{"start":11.46,"end":17.79,"cap":"GPS collars on elk, wolves, and pumas, located many times a day, revealed something new."}],"end":17.79},{"start":18.54,"sents":[{"start":18.54,"end":28.26,"cap":"Elk moved into open country at night and into forest by day, avoiding the peak hours of both predators: wolves hunting open terrain, pumas hunting rough forest."},{"start":28.66,"end":34.28,"cap":"This dynamic landscape of fear, invisible to the earlier instrument, left elk ample time to browse."}],"end":34.28},{"start":35.03,"sents":[{"start":35.03,"end":45.38,"cap":"Before risk could be observed at all, it had to be defined: the core or edge of a wolf territory, the presence of downed logs, the width of a viewshed, or the locations of kills."},{"start":45.78,"end":48.98,"cap":"Each operational definition carried a theory of what elk fear."}],"end":48.98},{"start":49.73,"sents":[{"start":49.73,"end":51.25,"cap":"Your own data are no different."},{"start":51.65,"end":57.76,"cap":"A lidar canopy height model is an inference from laser returns, classification thresholds, and a ground model."},{"start":58.16,"end":64.71,"cap":"An animal count is abundance multiplied by detection probability, and not detecting a species is not proof of its absence."}],"end":64.71}],"sig":"1027:0,0,0,0"},"obs-limits":{"dur":26.14,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.5,"cap":"Theory-ladenness does not mean anything goes."},{"start":3.9,"end":8.15,"cap":"The aspen stems were measured; they either grew past browse height or did not."},{"start":8.55,"end":16.01,"cap":"Ian Hacking argued that when independent methods, built on different theories, converge on the same result, we have good reason to believe it."}],"end":16.01},{"start":16.76,"sents":[{"start":16.76,"end":24.84,"cap":"Interpretivists meet the same problem with reflexivity: declaring the researcher’s position, because it shapes what is noticed and what is recorded."}],"end":24.84}],"sig":"416:0,0"},"models-card":{"dur":6,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.74,"cap":"Chapter seven."},{"start":2.14,"end":4.38,"cap":"Models, and why none of them is reality."}],"end":4.38}],"sig":"55:0"},"models-map":{"dur":54.46,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":5.33,"cap":"A map at a scale of one to one would be perfectly accurate and perfectly useless."},{"start":5.73,"end":8.24,"cap":"Models are valuable because they leave things out."},{"start":8.64,"end":12.89,"cap":"The statistician George Box put it bluntly: all models are wrong."}],"end":12.89},{"start":13.64,"sents":[{"start":13.64,"end":24.92,"cap":"Michael Weisberg distinguishes three kinds of idealization: simplifying for tractability, keeping only the factors that make a difference, and building several incompatible models on purpose."},{"start":25.32,"end":32.15,"cap":"Mary Morgan and Margaret Morrison describe models as mediators, partly independent of both theory and world."}],"end":32.15},{"start":32.9,"sents":[{"start":32.9,"end":40.97,"cap":"Richard Levins, whom you met in the first film, argued that no model can maximize generality, realism, and precision at once."},{"start":41.37,"end":48.93,"cap":"His remedy was robustness analysis: if several different models agree, the result is probably not an artifact of any one."},{"start":49.33,"end":53.16,"cap":"“Our truth,” he wrote, “is the intersection of independent lies.”"}],"end":53.16}],"sig":"813:0,0,0"},"models-boxes":{"dur":51.72,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.48,"cap":"Wolf, elk, aspen: three boxes and two arrows."},{"start":4.88,"end":8.66,"cap":"The model is clear, memorable, and wrong in ways that matter."}],"end":8.66},{"start":9.41,"sents":[{"start":9.41,"end":29.93,"cap":"The system it stands for has pumas, which killed a larger share of Northern Range elk than wolves did in most years from 1998 to 2004; grizzly and black bears, the main predators of elk calves; human hunters; a bison herd that grew fourfold; and beaver, drought, and incised streams."}],"end":29.93},{"start":30.68,"sents":[{"start":30.68,"end":33.96,"cap":"Models also travel beyond the conditions that built them."},{"start":34.36,"end":39.16,"cap":"One analysis estimated a fifteen-hundred-percent increase in willow crown volume."},{"start":39.56,"end":45.86,"cap":"Critics argue that the volume equation, calibrated on lightly browsed plants, was applied to heavily browsed ones."},{"start":46.26,"end":50.42,"cap":"An estimate is only as good as the model linking it to the quantity you care about."}],"end":50.42}],"sig":"730:0,0,0"},"models-pit":{"dur":45,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.7,"cap":"Models also act in the world."},{"start":3.1,"end":11.84,"cap":"Early wolf-removal programs assumed moose were caught in a predator pit, a low-density state held by predators, with a high-density state waiting above."},{"start":12.24,"end":16.85,"cap":"Kill enough wolves, the model said, and moose would climb out to a new equilibrium."}],"end":16.85},{"start":17.6,"sents":[{"start":17.6,"end":28.57,"cap":"François Messier found instead that wolf predation tends to hold moose at a single equilibrium, and a National Research Council review found little support for alternative stable states in wolf–moose systems."},{"start":28.97,"end":31.89,"cap":"A model of two states had helped justify real killing."}],"end":31.89},{"start":32.64,"sents":[{"start":32.64,"end":38.53,"cap":"Not every model is mathematical: a range map in a field guide and a hunting regulation are models too."},{"start":38.93,"end":43.7,"cap":"And a species distribution model estimates the realized niche, never the fundamental one."}],"end":43.7}],"sig":"724:0,0,0"},"cause-card":{"dur":6.39,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.6,"cap":"Chapter eight."},{"start":2,"end":4.79,"cap":"Causality: association is not explanation."}],"end":4.79}],"sig":"57:0"},"cause-assoc":{"dur":59.04,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.75,"cap":"Two variables can move together for many reasons."},{"start":4.15,"end":14.2,"cap":"One may cause the other; the other may cause the one; a third variable may cause both; or the association may be manufactured by how cases were selected."},{"start":14.6,"end":18.18,"cap":"Confounding, reverse causation, and collider bias."}],"end":18.18},{"start":18.93,"sents":[{"start":18.93,"end":19.94,"cap":"Here is a real puzzle."},{"start":20.34,"end":29.33,"cap":"Across western North America, adult female elk survived better where both pumas and wolves lived than where there was only one predator, or none."},{"start":29.73,"end":31.29,"cap":"Do two predators protect elk?"}],"end":31.29},{"start":32.04,"sents":[{"start":32.04,"end":33.17,"cap":"Almost certainly not."},{"start":33.57,"end":39.57,"cap":"Managers expecting heavy predation had already cut hunting quotas there, so management was a common cause of both."},{"start":39.97,"end":45.6,"cap":"Across the same forty-five populations, human harvest lowered survival far more than any predator."}],"end":45.6},{"start":46.35,"sents":[{"start":46.35,"end":52.57,"cap":"A related trap is Simpson’s paradox, where a trend that holds within every subgroup reverses once the groups are pooled."},{"start":52.97,"end":56.08,"cap":"The data alone cannot tell you whether to pool or stratify."},{"start":56.48,"end":57.74,"cap":"That takes a causal model."}],"end":57.74}],"sig":"897:0,0,0,0"},"cause-counter":{"dur":67.24,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.02,"cap":"What is a cause?"},{"start":2.42,"end":4.55,"cap":"David Hume answered regular succession."},{"start":4.95,"end":11.91,"cap":"David Lewis answered with counterfactuals: c caused e if, had c not happened, e would not have happened."},{"start":12.31,"end":18.75,"cap":"James Woodward answered with intervention: c causes e if changing c, and nothing else, would change e."}],"end":18.75},{"start":19.5,"sents":[{"start":19.5,"end":21.87,"cap":"Statisticians formalized the counterfactual."},{"start":22.27,"end":26.3,"cap":"Each unit has two potential outcomes, one with the treatment and one without."},{"start":26.7,"end":33.93,"cap":"Paul Holland called the catch the fundamental problem of causal inference: for any one unit, you observe only one of them."}],"end":33.93},{"start":34.68,"sents":[{"start":34.68,"end":37.46,"cap":"Wildlife biologists know this problem by another name."},{"start":37.86,"end":45.39,"cap":"Mortality is additive if a predator’s kills add to deaths from other causes, and compensatory if the animals killed would have died anyway."},{"start":45.79,"end":49.12,"cap":"That is a counterfactual claim about animals that are already dead."}],"end":49.12},{"start":49.87,"sents":[{"start":49.87,"end":51.43,"cap":"Evidence can still bear on it."},{"start":51.83,"end":58.72,"cap":"In Yellowstone, wolf-killed cow elk were most often about sixteen years old; hunter-killed cows, about four."},{"start":59.12,"end":65.94,"cap":"Old elk have little time left to live or breed, so wolf kills are more likely compensatory, and hunter kills more likely additive."}],"end":65.94}],"sig":"1044:0,0,0,0"},"cause-dag":{"dur":59.36,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":8.7,"cap":"Judea Pearl gave causal reasoning a picture: the directed acyclic graph, in which arrows show which variables affect which."},{"start":9.1,"end":13.29,"cap":"Wolves, pumas, bears, hunters, and drought point at elk."},{"start":13.69,"end":17.04,"cap":"Elk, bison, and water point at aspen and willow."},{"start":17.44,"end":18.73,"cap":"Beaver points at water."}],"end":18.73},{"start":19.48,"sents":[{"start":19.48,"end":21.33,"cap":"The graph tells you what to adjust for."},{"start":21.73,"end":29.46,"cap":"To estimate the effect of wolves on elk, block every back-door path, every route by which a common cause, such as management, links the two."},{"start":29.86,"end":35.8,"cap":"Pearl ranks causal questions on a ladder: association, intervention, and counterfactuals."}],"end":35.8},{"start":36.55,"sents":[{"start":36.55,"end":40.34,"cap":"Adam Ford and Jacob Goheen applied this logic to trophic cascades."},{"start":40.74,"end":49.75,"cap":"Three links must be shown: predators suppress herbivores; herbivores suppress plants; and so predators help plants."},{"start":50.15,"end":54.23,"cap":"In Yellowstone, exclosures establish the second link."},{"start":54.63,"end":58.06,"cap":"The first is the least certain, and the third is mixed."}],"end":58.06}],"sig":"817:0,0,0"},"cause-design":{"dur":77.58,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":7.62,"cap":"Ronald Fisher’s answer was randomization: assign treatments by chance, and confounders balance out on average."},{"start":8.02,"end":12.27,"cap":"Crossing two treatments in a factorial design also reveals whether they interact."}],"end":12.27},{"start":13.02,"sents":[{"start":13.02,"end":17.8,"cap":"On the Northern Range, researchers crossed simulated beaver dams with elk exclosures."},{"start":18.2,"end":20.05,"cap":"Either one alone sped willow growth."},{"start":20.45,"end":23.71,"cap":"Together, they let willows pass browse height in about five years."},{"start":24.11,"end":26.82,"cap":"Untreated controls never did, even after twenty."}],"end":26.82},{"start":27.57,"sents":[{"start":27.57,"end":30.54,"cap":"Paired experiments can separate top-down from bottom-up."},{"start":30.94,"end":37.94,"cap":"In Idaho, removing coyotes and pumas raised mule deer fawn survival slightly but did not change population growth."},{"start":38.34,"end":42.98,"cap":"In Colorado, feeding deer in winter raised population growth by thirteen percent a year."}],"end":42.98},{"start":43.73,"sents":[{"start":43.73,"end":44.85,"cap":"Weaker designs leak."},{"start":45.25,"end":51.56,"cap":"Many predator-removal programs had no controls and relaxed hunting at the same time, confounding by design."},{"start":51.96,"end":60.41,"cap":"And nature sometimes runs the experiment: when canine parvovirus collapsed Isle Royale’s wolves, moose grew faster and to higher numbers."}],"end":60.41},{"start":61.16,"sents":[{"start":61.16,"end":68.97,"cap":"When experiments are impossible, before-after-control-impact designs and Austin Bradford Hill’s viewpoints help weigh observational evidence."},{"start":69.37,"end":76.28,"cap":"Interpretive social science adds another kind of cause: the reasons that move people, such as a rancher’s choice to tolerate elk."}],"end":76.28}],"sig":"1231:0,0,0,0,0"},"under-card":{"dur":7.04,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.62,"cap":"Chapter nine."},{"start":2.02,"end":5.44,"cap":"Underdetermination: when evidence fits more than one theory."}],"end":5.44}],"sig":"74:0"},"under-holism":{"dur":48.27,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.62,"cap":"Any finite set of points can be threaded by infinitely many curves."},{"start":5.02,"end":11.13,"cap":"Underdetermination is the general form of that fact: evidence alone may not fix which theory is true."},{"start":11.53,"end":16.67,"cap":"Duhem and Quine’s holism makes it worse, because auxiliary assumptions can always be adjusted."}],"end":16.67},{"start":17.42,"sents":[{"start":17.42,"end":28.02,"cap":"Philosophers distinguish transient underdetermination, which better data or designs can resolve, from strong underdetermination, in which rival theories are empirically equivalent forever."},{"start":28.42,"end":32.73,"cap":"Most of what ecologists face is the transient kind, though it can last a long time."}],"end":32.73},{"start":33.48,"sents":[{"start":33.48,"end":38.03,"cap":"Hydrologists call it equifinality: many parameter sets fit the same record."},{"start":38.43,"end":41.1,"cap":"Ecologists know it as the pattern–process problem."},{"start":41.5,"end":46.97,"cap":"As the first film showed, neutral and niche models can produce the same species-abundance distribution."}],"end":46.97}],"sig":"769:0,0,0"},"under-decline":{"dur":70.38,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":15.34,"cap":"The Northern Range elk decline fits many stories: wolves; hunters taking females that left the park; drought; pumas; grizzly and black bears; competition with a growing bison herd."},{"start":15.74,"end":19.94,"cap":"A demographic analysis attributed the first decade mainly to hunting and drought."},{"start":20.34,"end":23.44,"cap":"No comparable analysis has apportioned the decline since."}],"end":23.44},{"start":24.19,"sents":[{"start":24.19,"end":25.57,"cap":"Some ties have been broken."},{"start":25.97,"end":31.09,"cap":"Since 2005, the share of the herd wintering outside the park rose from twenty to eighty percent."},{"start":31.49,"end":38.88,"cap":"It looked like elk fleeing wolves, but it was demographic: elk outside the park survived better, rather than individuals moving."}],"end":38.88},{"start":39.63,"sents":[{"start":39.63,"end":42.9,"cap":"And a design built to separate mechanisms did separate them."},{"start":43.3,"end":53.45,"cap":"Linking aspen recruitment to ten measures of predation risk and to changes in elk density, Brice and colleagues found risk effects eight to twenty-eight times weaker than density effects."}],"end":53.45},{"start":54.2,"sents":[{"start":54.2,"end":55.93,"cap":"For willow, the tie persists."},{"start":56.33,"end":64.65,"cap":"From the same data, one group sees a stalled system, possibly an alternative stable state held by bison, incised streams, and missing beaver."},{"start":65.05,"end":69.08,"cap":"Another sees willow height doubled in twenty years: a slow recovery."}],"end":69.08}],"sig":"1064:0,0,0,0"},"under-break":{"dur":48.73,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.69,"cap":"How do scientists choose when evidence does not?"},{"start":4.09,"end":11.61,"cap":"With theoretical virtues, such as simplicity, scope, and coherence with other knowledge, though choosing among the virtues is itself a judgment."}],"end":11.61},{"start":12.36,"sents":[{"start":12.36,"end":16.28,"cap":"Better, design discriminating tests, as Chamberlin and Platt urged."},{"start":16.68,"end":18.25,"cap":"Or weigh many models at once."},{"start":18.65,"end":28.51,"cap":"Kenneth Burnham and David Anderson’s multimodel inference ranks candidate models by information criteria such as AIC, and averages across them rather than crowning a single winner."}],"end":28.51},{"start":29.26,"sents":[{"start":29.26,"end":31.38,"cap":"Scale can also dissolve a contradiction."},{"start":31.78,"end":36.8,"cap":"Large carnivores feed smaller carnivores through carrion nearby, and kill them across landscapes."},{"start":37.2,"end":45.36,"cap":"Studies covering less than a thousand square kilometers tend to find positive associations; larger studies, negative ones."},{"start":45.76,"end":47.43,"cap":"Both are right, at their own scale."}],"end":47.43}],"sig":"772:0,0,0"},"bayes-card":{"dur":6.84,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.66,"cap":"Chapter ten."},{"start":2.06,"end":5.24,"cap":"Bayesian epistemology: how evidence should change belief."}],"end":5.24}],"sig":"70:0"},"bayes-credence":{"dur":46.76,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.3,"cap":"Bayesian epistemology treats belief as a matter of degree."},{"start":4.7,"end":9.19,"cap":"A credence is a probability, from zero to one, that a hypothesis is true."},{"start":9.59,"end":19,"cap":"Frank Ramsey argued that credences should obey the laws of probability: if they do not, a clever bookie could sell you a set of bets that loses whatever happens, a Dutch book."}],"end":19},{"start":19.75,"sents":[{"start":19.75,"end":22.62,"cap":"Bayes’ theorem says how evidence should change a credence."},{"start":23.02,"end":33.36,"cap":"The posterior probability of a hypothesis, given the evidence, is proportional to its prior probability times the likelihood: how probable the evidence would be if the hypothesis were true."}],"end":33.36},{"start":34.11,"sents":[{"start":34.11,"end":36.8,"cap":"Updating this way is called conditionalization."},{"start":37.2,"end":42.75,"cap":"Evidence confirms a hypothesis when it raises its probability, and disconfirms it when it lowers it."},{"start":43.15,"end":45.46,"cap":"On this view, confirmation comes in degrees."}],"end":45.46}],"sig":"751:0,0,0"},"bayes-lr":{"dur":50.86,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.42,"cap":"How strongly does evidence favor one hypothesis over another?"},{"start":4.82,"end":10.51,"cap":"The likelihood ratio answers: how much more probable the evidence is under one than under the other."},{"start":10.91,"end":13.95,"cap":"It is the factor by which the evidence should multiply your odds."}],"end":13.95},{"start":14.7,"sents":[{"start":14.7,"end":17.52,"cap":"Ignore the prior and you commit the base-rate fallacy."},{"start":17.92,"end":29.08,"cap":"Suppose a camera-trap classifier labels ninety-five percent of wolf photos correctly and mislabels one percent of coyote photos as wolves, in a region where one canid photo in a thousand is a wolf."},{"start":29.48,"end":32.63,"cap":"About nine in ten photos flagged as wolves are coyotes."}],"end":32.63},{"start":33.38,"sents":[{"start":33.38,"end":40.83,"cap":"Richard Royall separated three questions: what does the evidence say; what should I believe; and what should I do?"},{"start":41.23,"end":42.65,"cap":"They map onto our bands."},{"start":43.05,"end":49.56,"cap":"The likelihood ratio answers the first, the posterior the second, and a decision, with its costs, the third."}],"end":49.56}],"sig":"786:0,0,0"},"bayes-case":{"dur":71.02,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.71,"cap":"Read the Yellowstone debate as a sequence of updates."},{"start":4.11,"end":10.63,"cap":"The prior came from Isle Royale, where tree rings tracked the rise and fall of wolves and moose, and from Leopold’s story."},{"start":11.03,"end":15.35,"cap":"Early aspen studies raised belief in a strong cascade, driven by fear."}],"end":15.35},{"start":16.1,"sents":[{"start":16.1,"end":24.28,"cap":"Then a landscape test found no fear effect, random sampling found a weaker signal, density outweighed risk, and willow lagged."},{"start":24.68,"end":32.75,"cap":"Belief in some cascade on aspen survived; belief that fear drives it fell; uncertainty about its strength remains wide."}],"end":32.75},{"start":33.5,"sents":[{"start":33.5,"end":36.35,"cap":"Bayesian reading also guards against a common error."},{"start":36.75,"end":54.99,"cap":"Across sixteen pairs of large carnivores and mesocarnivores, the average abundance correlation was −0.18, with a 95 percent confidence interval from −0.41 to 0.05: not significant, at p = 0.11."}],"end":54.99},{"start":55.74,"sents":[{"start":55.74,"end":58.86,"cap":"Not significant is not the same as no effect."},{"start":59.26,"end":65.59,"cap":"Read with a flat prior, that interval puts the probability that the average effect is negative near ninety-four percent."},{"start":65.99,"end":69.72,"cap":"The evidence leans toward suppression, but the data are mostly correlative."}],"end":69.72}],"sig":"1078:0,0,0,0"},"bayes-priors":{"dur":30.49,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.34,"cap":"Where do priors come from?"},{"start":2.74,"end":4.17,"cap":"Critics call them subjective."},{"start":4.57,"end":14.61,"cap":"Bayesians reply that with enough shared evidence, different priors converge, because the data wash them out, and that writing priors down exposes assumptions other methods leave hidden."}],"end":14.61},{"start":15.36,"sents":[{"start":15.36,"end":17.19,"cap":"Deborah Mayo offers the main rival."},{"start":17.59,"end":25.02,"cap":"On her error-statistical view, evidence supports a claim when the claim has passed a severe test, one it would probably have failed if it were false."},{"start":25.42,"end":29.19,"cap":"The question is not how much to believe, but how well the claim has been probed."}],"end":29.19}],"sig":"509:0,0"},"rep-card":{"dur":7.53,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.82,"cap":"Chapter eleven."},{"start":2.22,"end":5.93,"cap":"Replication: would it happen again, and elsewhere?"}],"end":5.93}],"sig":"66:0"},"rep-defs":{"dur":33.12,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.39,"cap":"When a finding holds up, what exactly held?"},{"start":3.79,"end":14.13,"cap":"The National Academies distinguish reproducibility, where the same data and code give the same result, from replicability, where a new study with new data reaches a consistent result."}],"end":14.13},{"start":14.88,"sents":[{"start":14.88,"end":15.95,"cap":"Two more words help."},{"start":16.35,"end":21.5,"cap":"Generalizability asks whether a result extends to other places, times, and populations."},{"start":21.9,"end":25.56,"cap":"Robustness asks whether it survives reasonable changes of analysis."},{"start":25.96,"end":31.82,"cap":"When twenty-nine teams analyzed one data set, their estimates ranged from slightly negative to strongly positive."}],"end":31.82}],"sig":"518:0,0"},"rep-crisis":{"dur":59.7,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":10.35,"cap":"In 2005, John Ioannidis argued that most published research findings are false, given small samples, small effects, and flexible analyses."},{"start":10.75,"end":14.95,"cap":"In 2015, a large collaboration repeated one hundred psychology studies."},{"start":15.35,"end":21.08,"cap":"Ninety-seven percent of the originals had significant results; thirty-six percent of the replications did."}],"end":21.08},{"start":21.83,"sents":[{"start":21.83,"end":43.08,"cap":"The causes are familiar: low statistical power; publication bias toward positive results; p-hacking, trying analyses until one is significant; HARKing, presenting a hypothesis formed after the results as if it came first; and the garden of forking paths, where each reasonable choice raises the chance of a false positive."}],"end":43.08},{"start":43.83,"sents":[{"start":43.83,"end":45.35,"cap":"Ecology is not exempt."},{"start":45.75,"end":49.25,"cap":"Many ecologists surveyed admit to questionable research practices."},{"start":49.65,"end":58.4,"cap":"And Stuart Hurlbert showed in 1984 that many field experiments were pseudoreplicated, treating repeated measurements of one unit as independent replicates."}],"end":58.4}],"sig":"891:0,0,0"},"rep-30km":{"dur":77.44,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":11.95,"cap":"In the Madison Headwaters of central Yellowstone, wolves met a non-migratory herd of four to six hundred elk, wintering on patches kept bare by thermal features and hemmed in by deep snow."},{"start":12.35,"end":17.29,"cap":"Cow survival fell by five to fifteen percent, and elk numbers fell five- to tenfold."}],"end":17.29},{"start":18.04,"sents":[{"start":18.04,"end":23.52,"cap":"Less than thirty kilometers away, on the Northern Range, the effect of the same wolves is still debated."},{"start":23.92,"end":27.42,"cap":"And on two Alaskan islands, wolves nearly eliminated the deer."},{"start":27.82,"end":29.77,"cap":"Same predator, different worlds."}],"end":29.77},{"start":30.52,"sents":[{"start":30.52,"end":33.26,"cap":"Replication across many sites sharpens the pattern."},{"start":33.66,"end":39.12,"cap":"Across eleven elk populations, only grizzly predation added to newborn calf mortality."},{"start":39.52,"end":42.74,"cap":"Across forty-five, human harvest outweighed every predator."},{"start":43.14,"end":47.59,"cap":"Across fifty-two removal experiments, killing predators rarely raised abundance."}],"end":47.59},{"start":48.34,"sents":[{"start":48.34,"end":50.55,"cap":"Generalizing also depends on where we look."},{"start":50.95,"end":62.16,"cap":"About seventy percent of studies of carnivore interactions are in protected areas, yet only fifteen percent of large-carnivore range in North America is protected, and four percent is strictly protected from hunting."}],"end":62.16},{"start":62.91,"sents":[{"start":62.91,"end":65.4,"cap":"The review’s answer is a set of scope conditions."},{"start":65.8,"end":76.14,"cap":"Predators most often limit their prey where prey are spatially confined, where they share a predator with a more resilient prey species, or where several predators specialize on different life stages."}],"end":76.14}],"sig":"1266:0,0,0,0,0"},"rep-remedies":{"dur":33.77,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":14.63,"cap":"Remedies are spreading: preregistration and registered reports, which fix hypotheses and analyses before the data are seen; open data and code; and coordinated experiments run the same way at many sites."},{"start":15.03,"end":19.01,"cap":"For predictive models, transferability must be tested, not assumed."}],"end":19.01},{"start":19.76,"sents":[{"start":19.76,"end":21.99,"cap":"Interpretive research has its own standards."},{"start":22.39,"end":32.47,"cap":"Instead of validity and reliability, it asks for trustworthiness: credibility, transferability, dependability, and confirmability."}],"end":32.47}],"sig":"447:0,0"},"values-card":{"dur":6,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.59,"cap":"Chapter twelve."},{"start":1.99,"end":4.09,"cap":"Values, objectivity, and judgment."}],"end":4.09}],"sig":"50:0"},"values-risk":{"dur":48.39,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.68,"cap":"Should science be value-free?"},{"start":3.08,"end":9.67,"cap":"The traditional ideal says values may guide which questions we ask and how we use the answers, but not how we judge evidence."},{"start":10.07,"end":14.72,"cap":"Hans Reichenbach separated the context of discovery from the context of justification."}],"end":14.72},{"start":15.47,"sents":[{"start":15.47,"end":17.95,"cap":"In 1953, Richard Rudner objected."},{"start":18.35,"end":26.45,"cap":"Evidence never makes a hypothesis certain, so accepting one means judging the evidence strong enough, and how strong is enough depends on the cost of being wrong."},{"start":26.85,"end":29.75,"cap":"Heather Douglas calls this the argument from inductive risk."}],"end":29.75},{"start":30.5,"sents":[{"start":30.5,"end":34.27,"cap":"Epistemic values, such as accuracy and simplicity, bear on truth."},{"start":34.67,"end":40.7,"cap":"Non-epistemic values, such as safety, livelihoods, or the survival of a species, bear on consequences."},{"start":41.1,"end":47.09,"cap":"Douglas argues that the second kind may legitimately set evidential thresholds, but must never stand in for evidence."}],"end":47.09}],"sig":"788:0,0,0"},"values-caribou":{"dur":56.46,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":11.24,"cap":"Mountain caribou declined by fifty-one percent between 1991 and 2023, and fifteen of forty-one subpopulations are now functionally extirpated."},{"start":11.64,"end":19.68,"cap":"Logging opened forests to moose and deer, which supported more wolves, which killed more caribou: apparent competition."}],"end":19.68},{"start":20.43,"sents":[{"start":20.43,"end":23,"cap":"Recovery actions have included killing wolves."},{"start":23.4,"end":28.45,"cap":"Conclude that wolves are not limiting caribou when they are, and a population disappears."},{"start":28.85,"end":32.52,"cap":"Conclude that they are when they are not, and wolves die for nothing."},{"start":32.92,"end":36.18,"cap":"Which error is worse is not a question the data can answer alone."}],"end":36.18},{"start":36.93,"sents":[{"start":36.93,"end":39.39,"cap":"Values also shape which impacts get counted."},{"start":39.79,"end":48.22,"cap":"Where wolves recolonized Wisconsin, deer–vehicle collisions fell by about a quarter, with benefits estimated at sixty-three times the losses of livestock."},{"start":48.62,"end":55.16,"cap":"Puma recovery in the eastern United States was projected to prevent one hundred fifty-five human deaths over thirty years."}],"end":55.16}],"sig":"858:0,0,0"},"values-baseline":{"dur":37.93,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.34,"cap":"What counts as recovery?"},{"start":2.74,"end":10.93,"cap":"Much of the disagreement over Yellowstone’s willow and aspen, Wilmers and colleagues conclude, stems from definitions and from uncertain baselines."},{"start":11.33,"end":20.09,"cap":"Should recovery be measured against the landscape before European colonization, already shaped by Indigenous peoples, or against a landscape without people at all?"}],"end":20.09},{"start":20.84,"sents":[{"start":20.84,"end":31.25,"cap":"Michael Soulé called conservation biology a crisis discipline: it must act before the evidence is complete, and its goals, such as keeping species and processes, are values."},{"start":31.65,"end":36.63,"cap":"Deciding how many carnivores a landscape should hold is an ecological question and a political one."}],"end":36.63}],"sig":"612:0,0"},"values-social":{"dur":62.78,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.88,"cap":"If individual scientists carry values, where does objectivity come from?"},{"start":5.28,"end":13.95,"cap":"Robert Merton described the norms of science: communalism, universalism, disinterestedness, and organized skepticism."},{"start":14.35,"end":20.12,"cap":"Helen Longino located objectivity in communities that expose claims to criticism and respond to it."}],"end":20.12},{"start":20.87,"sents":[{"start":20.87,"end":29.55,"cap":"Sandra Harding argued for strong objectivity: starting research from the standpoints of marginalized groups reveals assumptions a dominant view cannot see."},{"start":29.95,"end":36.14,"cap":"Heather Douglas notes that objectivity is not one thing but several, from fair procedures to reliable results."}],"end":36.14},{"start":36.89,"sents":[{"start":36.89,"end":39.58,"cap":"The Yellowstone debate shows criticism at work."},{"start":39.98,"end":47.73,"cap":"Comments and replies sharpened sampling designs, separated fear from density, and produced shared standards for demonstrating a cascade."}],"end":47.73},{"start":48.48,"sents":[{"start":48.48,"end":50.2,"cap":"The two traditions differ here too."},{"start":50.6,"end":54.82,"cap":"Postpositivism aims at value neutrality while studying how values intrude."},{"start":55.22,"end":61.48,"cap":"Interpretivism makes values explicit through reflexivity, treating the researcher’s commitments as part of the evidence."}],"end":61.48}],"sig":"974:0,0,0,0"},"demarc-card":{"dur":7.36,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.93,"cap":"Chapter thirteen."},{"start":2.33,"end":5.76,"cap":"Demarcation: what counts as science, and who decides."}],"end":5.76}],"sig":"71:0"},"demarc-stakes":{"dur":38.91,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.39,"cap":"What counts as science?"},{"start":2.79,"end":6.44,"cap":"The demarcation problem sounds academic until a court must decide."},{"start":6.84,"end":15.62,"cap":"In 1982, a federal judge struck down an Arkansas law requiring that creation science be taught alongside evolution, ruling that it was not science."},{"start":16.02,"end":19.65,"cap":"In 2005, another court ruled the same of intelligent design."}],"end":19.65},{"start":20.4,"sents":[{"start":20.4,"end":30.65,"cap":"In 1993, the Supreme Court’s Daubert decision asked judges to screen expert testimony by testability, peer review, error rates, standards, and general acceptance."},{"start":31.05,"end":37.61,"cap":"Funders, journals, and environmental assessments draw similar lines, and those lines decide whose knowledge shapes decisions."}],"end":37.61}],"sig":"589:0,0"},"demarc-criteria":{"dur":75.94,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.58,"cap":"Each philosophy we have met offered a criterion."},{"start":3.98,"end":6.75,"cap":"The logical positivists: verifiability."},{"start":7.15,"end":9.18,"cap":"Popper: falsifiability."},{"start":9.58,"end":12.31,"cap":"Kuhn: a tradition of puzzle-solving."},{"start":12.71,"end":15.9,"cap":"Lakatos: a progressive research program."},{"start":16.3,"end":24.09,"cap":"And Paul Thagard: a pseudoscience is a field that stagnates while its rivals progress, and whose practitioners ignore that fact."}],"end":24.09},{"start":24.84,"sents":[{"start":24.84,"end":32.94,"cap":"The courts leaned on methodological naturalism: science explains natural phenomena by natural causes, whatever one believes beyond them."},{"start":33.34,"end":40.06,"cap":"Merton and Longino point instead to institutions: open criticism, peer review, and shared standards."}],"end":40.06},{"start":40.81,"sents":[{"start":40.81,"end":44.28,"cap":"In 1983, Larry Laudan declared the problem dead."},{"start":44.68,"end":48.7,"cap":"No set of necessary and sufficient conditions had survived counterexamples."},{"start":49.1,"end":54.58,"cap":"Astrology makes testable claims and fails them; much good science is hard to falsify."}],"end":54.58},{"start":55.33,"sents":[{"start":55.33,"end":57.18,"cap":"Others revived it in looser form."},{"start":57.58,"end":63.72,"cap":"Massimo Pigliucci treats science as a cluster concept, a family resemblance with no single essence."},{"start":64.12,"end":69.34,"cap":"Paul Hoyningen-Huene argues that science differs from everyday knowledge by being more systematic."},{"start":69.74,"end":74.64,"cap":"And the German word Wissenschaft names all systematic knowledge, from physics to history."}],"end":74.64}],"sig":"1102:0,0,0,0"},"demarc-matrix":{"dur":54.69,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":5.86,"cap":"Now apply the criteria to our two research traditions, with astrology as a contrast."},{"start":6.26,"end":10.43,"cap":"Under verifiability, none fits cleanly; even physics strained it."},{"start":10.83,"end":22.23,"cap":"Under falsifiability, postpositivist natural science fits by design, interpretive research fits in part, and astrology, awkwardly, fits too: its predictions can be tested, and they fail."}],"end":22.23},{"start":22.98,"sents":[{"start":22.98,"end":36.94,"cap":"Under institutional norms and Thagard’s test of progress, interpretive social research qualifies and astrology does not: no community criticizes and revises its claims, and it has stood still for centuries while its rivals advanced."}],"end":36.94},{"start":37.69,"sents":[{"start":37.69,"end":46.19,"cap":"Under cluster or systematicity accounts, or Wissenschaft, interpretive research qualifies easily; in German it has always been science."},{"start":46.59,"end":49.42,"cap":"Whether English calls it science depends on the definition."},{"start":49.82,"end":51.91,"cap":"The underlying practices do not change."},{"start":52.31,"end":53.39,"cap":"Only the label does."}],"end":53.39}],"sig":"828:0,0,0"},"demarc-kaibab":{"dur":50.16,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.12,"cap":"Demarcation is usually aimed at fields outside science."},{"start":4.52,"end":6.29,"cap":"The Kaibab story points inward."},{"start":6.69,"end":15.46,"cap":"For decades, a weakly tested account of deer and predators lived in textbooks, retold by scientists and conservationists alike, until Caughley went back to the records."}],"end":15.46},{"start":16.21,"sents":[{"start":16.21,"end":18.44,"cap":"Nothing about its subject was unscientific."},{"start":18.84,"end":25.16,"cap":"What failed was practice: one poorly measured case, an untested rival, and too little criticism."},{"start":25.56,"end":27.29,"cap":"What corrected it was practice too."}],"end":27.29},{"start":28.04,"sents":[{"start":28.04,"end":33.79,"cap":"So demarcation concerns how claims are tested, criticized, and corrected, more than the prestige of a label."},{"start":34.19,"end":42.55,"cap":"Under a narrow definition, postpositivist natural science is the central case and interpretive research is science in an institutional sense."},{"start":42.95,"end":44.93,"cap":"Under a broad one, both qualify."},{"start":45.33,"end":46.75,"cap":"The choice has consequences."},{"start":47.15,"end":48.06,"cap":"Make it knowingly."}],"end":48.06}],"sig":"763:0,0,0.8"},"syn-card":{"dur":7.29,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.87,"cap":"Chapter fourteen."},{"start":2.27,"end":5.69,"cap":"Synthesis: observe, infer, claim."}],"end":5.69}],"sig":"51:0"},"syn-audit":{"dur":85.31,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":5.57,"cap":"Return to the claim that wolves restored Yellowstone, and audit it band by band."},{"start":5.97,"end":26.11,"cap":"Observed: elk counts, from more than nineteen thousand to under four thousand, then back to seven to nine; aspen saplings escaping browse in many stands; willow taller, but mostly still below browse height; bison up fourfold; incised channels; few beaver dams."}],"end":26.11},{"start":26.86,"sents":[{"start":26.86,"end":31.37,"cap":"Inferred: browsing limits aspen and willow, as exclosures show."},{"start":31.77,"end":36.02,"cap":"Several predators, and people, reduced elk, in shares not yet apportioned."},{"start":36.42,"end":39.09,"cap":"Density effects outweighed fear effects on aspen."},{"start":39.49,"end":43.01,"cap":"Each inference rests on sampling designs and assumptions we have examined."}],"end":43.01},{"start":43.76,"sents":[{"start":43.76,"end":55.02,"cap":"Claimable: large-carnivore recovery, together with hunting, drought, other predators, and bison, contributed to elk decline and to partial, local recovery of aspen."},{"start":55.42,"end":59.34,"cap":"Willow recovery is constrained, perhaps in an alternative stable state."},{"start":59.74,"end":61.92,"cap":"The strength of the cascade is still contested."},{"start":62.32,"end":65.16,"cap":"Less lovely than the viral story, and better warranted."}],"end":65.16},{"start":65.91,"sents":[{"start":65.91,"end":75.35,"cap":"Across North America, Wilmers and colleagues conclude, humans are the dominant driver of ungulate dynamics, and predator limitation is real but conditional."},{"start":75.75,"end":78.93,"cap":"Can predator restoration repair disrupted ecosystems?"},{"start":79.33,"end":84.01,"cap":"Sometimes, partly, and slowly, which is why preventing their loss matters most."}],"end":84.01}],"sig":"1237:0,0,0,0"},"syn-seven":{"dur":41.22,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":5.06,"cap":"Here is an audit you can take to any study, news story, or exam question."},{"start":5.46,"end":7.96,"cap":"One: what was observed, and how?"},{"start":8.36,"end":11.54,"cap":"Two: what was inferred, under which assumptions?"},{"start":11.94,"end":14.39,"cap":"Three: which alternatives remain?"}],"end":14.39},{"start":15.14,"sents":[{"start":15.14,"end":18.6,"cap":"Four: how strong is the evidence, and what would change your mind?"},{"start":19,"end":22.9,"cap":"Five: has it been replicated, and where does it generalize?"},{"start":23.3,"end":26.66,"cap":"Six: which values and stakes shape the claim?"},{"start":27.06,"end":31.79,"cap":"Seven: what would another tradition of inquiry ask that this one did not?"}],"end":31.79},{"start":32.54,"sents":[{"start":32.54,"end":34.26,"cap":"No tradition owns these questions."},{"start":34.66,"end":39.92,"cap":"Postpositivists and interpretivists answer them in their own ways, and each can hold the other to them."}],"end":39.92}],"sig":"575:0,0,0"},"syn-review":{"dur":39.75,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.73,"cap":"Before you go, rehearse."},{"start":3.13,"end":7.11,"cap":"What separates induction from abduction, and where does strong inference fit?"},{"start":7.51,"end":10.75,"cap":"Why does the Duhem–Quine thesis complicate falsification?"},{"start":11.15,"end":13.42,"cap":"What did Kuhn mean by incommensurability?"}],"end":13.42},{"start":14.17,"sents":[{"start":14.17,"end":17.48,"cap":"Why is compensatory mortality a counterfactual claim?"},{"start":17.88,"end":19.93,"cap":"What is the argument from inductive risk?"},{"start":20.33,"end":25.05,"cap":"And how does the answer to “what counts as science?” change with the criterion you choose?"}],"end":25.05},{"start":26.8,"sents":[{"start":26.8,"end":29.42,"cap":"The ecological theater was a stage for evolution."},{"start":29.82,"end":31.58,"cap":"This one has been a stage for knowing."},{"start":31.98,"end":36.45,"cap":"Observe carefully, infer honestly, and claim no more than your warrant allows."}],"end":36.45}],"sig":"558:0,1,2"}};
